"use client";
import type { PremiumPrice } from "@/components/premium-upgrade-dialog";
import { useRoleSuggestions } from "@/components/role-allowance";
import {
  startTransition,
  useEffect,
  useRef,
  useState,
  useTransition,
} from "react";
import { useRouter } from "next/navigation";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  saveTemplate,
  archiveTemplate,
  saveContact,
  checkContactEmail,
  archiveContact,
} from "@/lib/actions";
import type { ActionResult } from "@/lib/errors";
import Link from "next/link";
import { suggestName } from "@/lib/imports";
import { normalizedEmail } from "@/lib/validation";
import {
  TemplatePreview,
  previewParts,
  type PreviewContact,
} from "@/components/template-preview";
import {
  useWorkspaceEntitlements,
  refreshWorkspaceAccess,
} from "@/components/workspace-quota";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
