import { RoleChoices } from "@/components/preferences";

import {
  SuccessConfirmation,
  useSuccessNotification,
} from "@/components/notifications";

export function useUnsavedChanges(dirty: boolean, preserveQuery = false) {
  useEffect(() => {
    if (!dirty) return;
    const unload = (e: BeforeUnloadEvent) => {
      e.preventDefault();
    };
    const click = (e: MouseEvent) => {
      if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey)
        return;
      const link = (e.target as Element).closest("a");
      if (link?.target === "_blank" || link?.hasAttribute("download")) return;
      if (
        link &&
        preserveQuery &&
        new URL(link.href).pathname === window.location.pathname
      )
        return;
      if (
        link &&
        link.href !== window.location.href &&
        !window.confirm("Leave this page and discard your unsaved changes?")
      ) {
        e.preventDefault();
        e.stopPropagation();
      }
    };
    window.addEventListener("beforeunload", unload);
    document.addEventListener("click", click, true);
    return () => {
      window.removeEventListener("beforeunload", unload);
      document.removeEventListener("click", click, true);
    };
  }, [dirty, preserveQuery]);
}
export function Feedback({
  result,
  successConfirmation = false,
  planLabel = "Paid",
  inlineFieldErrors = false,
}: {
  inlineFieldErrors?: boolean;
  result?: ActionResult;
  successConfirmation?: boolean;
  planLabel?: "Paid" | "Premium";
}) {
  useEffect(() => {
    if (result?.ok === false && result.code) refreshWorkspaceAccess();
  }, [result]);
  if (
    inlineFieldErrors &&
    result?.ok === false &&
    Object.values(result.fieldErrors ?? {}).includes(result.message)
  )
    return null;
  if (successConfirmation && result?.ok)
    return <SuccessConfirmation>{result.message}</SuccessConfirmation>;
  return (
    <p
      aria-live="polite"
      role={result?.ok === false ? "alert" : undefined}
      className={`min-h-5 text-sm ${result?.ok === false ? "text-error-deep" : "text-body"}`}
    >
      {planLabel === "Premium"
        ? result?.message?.replace(/\bPaid\b/g, "Premium")
        : result?.message}
    </p>
  );
}
function FieldError({ result, name }: { result?: ActionResult; name: string }) {
  return result?.fieldErrors?.[name] ? (
    <p id={`error-${name}`} className="mt-2 text-xs text-error-deep">
      {result.fieldErrors[name]}
    </p>
  ) : null;
}
export function DeleteButton({
  id,
  kind,
}: {
  id: string;
  kind: "template" | "contact";
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const [pending, start] = useTransition();
  const [result, setResult] = useState<ActionResult>();
  const router = useRouter();
  return (
    <>
      <Button variant="ghost" onClick={() => dialog.current?.showModal()}>
        Delete
      </Button>
      <dialog ref={dialog} aria-labelledby={`delete-${id}`}>
        <h2 id={`delete-${id}`} className="text-xl font-semibold">
          Delete this {kind}?
        </h2>
        <p className="mt-3 text-sm leading-6 text-body">
          It will be removed from your list. Previously queued emails and
          history are preserved.
        </p>
        <div className="mt-6 flex justify-end gap-2">
          <Button variant="outline" onClick={() => dialog.current?.close()}>
            Cancel
          </Button>
          <Button
            variant="destructive"
            disabled={pending}
            onClick={() =>
              start(async () => {
                const r = await (
                  kind === "template" ? archiveTemplate : archiveContact
                )(id);
                setResult(r);
                if (r.ok) {
                  dialog.current?.close();
                  router.refresh();
                }
              })
            }
          >
            {pending ? "Deleting…" : "Delete"}
          </Button>
        </div>
        <Feedback result={result} />
      </dialog>
    </>
  );
}
const example = {
  subject: "Exploring {{role}} opportunities at {{company}}",
  body: "Hi {{name}},\n\nI’m interested in {{role}} opportunities at {{company}}.\nI’d love to discuss how my experience could help your team.\n\nPortfolio: https://example.com/your-portfolio\nGitHub: https://github.com/your-username\nLinkedIn: https://www.linkedin.com/in/your-username\n\nI’ve attached my resume PDF for your review.\n\nThank you for your time. If you prefer no further messages, please reply and I’ll stop.\nYour name",
};
export function TemplateForm({
  template,
  contacts = [],
  freeEligible = true,
  cancelHref,
  successHref,
  planLabel = "Paid",
}: {
  contacts?: PreviewContact[];
  freeEligible?: boolean;
  cancelHref?: string;
  successHref?: string;
  planLabel?: "Paid" | "Premium";
  template?: { id: string; name: string; subject: string; body: string };
}) {
  const access = useWorkspaceEntitlements();
  const planLocked = access.limits.savedTemplates !== null && !freeEligible;
  const upgrade = usePremiumUpgrade();
  const [result, setResult] = useState<ActionResult>();
  const [pending, start] = useTransition();
  const [dirty, setDirty] = useState(false);
  useUnsavedChanges(dirty);
  const router = useRouter();
  const notifySuccess = useSuccessNotification();
  const formRef = useRef<HTMLFormElement>(null);
  const [draft, setDraft] = useState({
    subject: template?.subject ?? "",
    body: template?.body ?? "",
  });
  const [tab, setTab] = useState<"write" | "preview">("write");
  const [tipsOpen, setTipsOpen] = useState(false);
  const lastFocused = useRef<"subject" | "body">("body");
  const selection = useRef({
    subject: { start: 0, end: 0 },
    body: { start: 0, end: 0 },
  });
  const [name, setName] = useState(template?.name ?? "");
  const placeholderErrors = [
    ...new Set(
      [draft.subject, draft.body].flatMap(
        (text) =>
          previewParts(text, { name: "", company: "", role: "" }).errors,
      ),
    ),
  ];
  const canSave = Boolean(
    name.trim() &&
    draft.subject.trim() &&
    draft.body.trim() &&
    !placeholderErrors.length,
  );
  const words = draft.body.trim() ? draft.body.trim().split(/\s+/).length : 0;
  function syncDraft() {
    const form = formRef.current;
    if (form) {
      setName((form.elements.namedItem("name") as HTMLInputElement).value);
      setDraft({
        subject: (form.elements.namedItem("subject") as HTMLInputElement).value,
        body: (form.elements.namedItem("body") as HTMLTextAreaElement).value,
      });
    }
  }
  useEffect(() => {
    if (!pending && result?.ok === false) {
      requestAnimationFrame(() =>
        formRef.current
          ?.querySelector<HTMLElement>("[aria-invalid='true']")
          ?.focus(),
      );
    }
  }, [result, pending]);
  return (
    <div className="template-editor" data-active-tab={tab}>
      <div
        className="template-editor-tabs hidden [@media(max-width:_959px)]:flex [@media(max-width:_959px)]:gap-1.5 [@media(max-width:_959px)]:p-1 [@media(max-width:_959px)]:mb-5 [@media(max-width:_959px)]:[border:1px_solid_var(--border)] [@media(max-width:_959px)]:rounded-[12px] [@media(max-width:_959px)]:[background:var(--card)]"
        role="tablist"
        aria-label="Template editor"
      >
        {(["write", "preview"] as const).map((value, index) => (
          <button
            key={value}
            id={`template-tab-${value}`}
            type="button"
            role="tab"
            aria-selected={tab === value}
            aria-controls={
              value === "write"
                ? "template-panel-write"
                : "template-pane-preview"
            }
            tabIndex={tab === value ? 0 : -1}
            onClick={() => setTab(value)}
            onKeyDown=[REDACTED_SECRET]
              if (
                !["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)
              )
                return;
              event.preventDefault();
              const next =
                event.key === "Home"
                  ? "write"
                  : event.key === "End"
                    ? "preview"
                    : index === 0
                      ? "preview"
                      : "write";
              setTab(next);
              document.getElementById(`template-tab-${next}`)?.focus();
            }}
          >
            {value === "write" ? "Write" : "Preview"}
          </button>
        ))}
      </div>
      <div className="template-editor-grid grid grid-cols-[repeat(2,_minmax(0,_1fr))] items-start gap-5 [@media(max-width:_959px)]:grid-cols-[minmax(0,_1fr)]">
        <div
          id="template-panel-write"
          role="tabpanel"
          aria-labelledby="template-tab-write"
          className={cn(
            "template-editor-write min-w-0",
            tab === "preview" && "[@media(max-width:_959px)]:hidden",
          )}
        >
          <form
            ref={formRef}
            id="template-pane-write"
            aria-labelledby="template-tab-write"
            className="panel flex flex-col gap-4.5 p-5.5 [background:var(--card)] [border:1px_solid_var(--border)] min-h-[calc(100dvh_-_260px)] [@media(max-width:_959px)]:min-h-0 [@media(max-width:_959px)]:p-4"
            onClickCapture={(event) => {
              if (!planLocked || pending || !(event.target instanceof Element))
                return;
              const control = event.target.closest<HTMLElement>(
                "input:not([type='hidden']), textarea, button",
              );
              if (!control) return;
              event.preventDefault();
              event.stopPropagation();
              upgrade({ feature: "templates", trigger: control });
            }}
            onKeyDownCapture=[REDACTED_SECRET]
              if (
                !planLocked ||
                pending ||
                !["Enter", " "].includes(event.key) ||
                !(event.target instanceof Element)
              )
                return;
              const control = event.target.closest<HTMLElement>(
                "input:not([type='hidden']), textarea",
              );
              if (!control) return;
              event.preventDefault();
              event.stopPropagation();
              upgrade({ feature: "templates", trigger: control });
            }}
            onChange={() => {
              setDirty(true);
              setResult((current) => (current?.ok ? undefined : current));
              syncDraft();
            }}
            onSubmit={(event) => {
              event.preventDefault();
              if (pending) return;
              if (planLocked) return upgrade({ feature: "templates" });
              if (!canSave) return;
              const form = new FormData(event.currentTarget);
              setResult(undefined);
              start(async () => {
                const r = await saveTemplate(form);
                setResult(r);
                if (!r.ok) setTab("write");
                if (r.ok) {
                  notifySuccess("Template saved successfully.");
                  setDirty(false);
                  if (!template) {
                    formRef.current?.reset();
                    syncDraft();
                  }
                  if (successHref) router.replace(successHref);
                  else router.refresh();
                }
              });
            }}
          >
            {planLocked && (
              <FeatureLock
                upgradeFeature="templates"
                planLabel={planLabel}
                feature={
                  template
                    ? "Editing this retained template"
                    : "Additional saved templates"
                }
              />
            )}
            {template && <input type="hidden" name="id" value={template.id} />}
            <div className="template-editor-fields grid grid-cols-[minmax(0,_1fr)_minmax(0,_1.4fr)] gap-3.5 [@media(max-width:_959px)]:grid-cols-[minmax(0,_1fr)]">
              <div className="min-w-0">
                <label
                  htmlFor="template-name"
                  className="mb-2 block text-sm font-medium"
                >
                  Template name
                </label>
                <Input
                  id="template-name"
                  className="read-only:cursor-pointer"
                  readOnly={planLocked}
                  disabled={pending}
                  aria-invalid={!!result?.fieldErrors?.name}
                  aria-describedby={
                    result?.fieldErrors?.name ? "error-name" : undefined
                  }
                  name="name"
                  defaultValue={template?.name}
                  required
                  maxLength={100}
                  autoComplete="off"
                  placeholder="A first introduction…"
                />
                <FieldError result={result} name="name" />
              </div>
              <div className="min-w-0">
                <label
                  htmlFor="template-subject"
                  className="mb-2 block text-sm font-medium"
                >
                  Subject
                </label>
                <Input
                  onFocus={() => {
                    lastFocused.current = "subject";
                  }}
                  onSelect={(event) => {
                    selection.current.subject = {
                      start: event.currentTarget.selectionStart ?? 0,
                      end: event.currentTarget.selectionEnd ?? 0,
                    };
                  }}
                  id="template-subject"
                  className="read-only:cursor-pointer"
                  readOnly={planLocked}
                  disabled={pending}
                  aria-invalid={!!result?.fieldErrors?.subject}
                  aria-describedby={
                    result?.fieldErrors?.subject ? "error-subject" : undefined
                  }
                  name="subject"
                  defaultValue={template?.subject}
                  required
                  maxLength={250}
                  autoComplete="off"
                  placeholder="Exploring {{role}} opportunities at {{company}}…"
                />
                <FieldError result={result} name="subject" />
              </div>
            </div>
            <div className="template-editor-message flex flex-col gap-2 flex-1 min-w-0">
              <div className="template-editor-message-header flex items-center justify-between gap-2.5 flex-wrap">
                <label
                  htmlFor="template-body"
                  className="m-0 block text-sm font-medium"
                >
                  Message
                </label>
                <div className="template-editor-chips flex flex-wrap gap-1.5">
                  {["name", "company", "role"].map((token) => (
                    <Button
                      key={token}
                      type="button"
                      variant="outline"
                      className="cursor-pointer chip min-h-11 max-w-full whitespace-normal wrap-anywhere [border:1px_dashed_var(--border)] rounded-full [background:transparent] text-link [font:500_12px_ui-monospace,_monospace] placeholder-chip [border:1px_solid_var(--border-hover)] [background:var(--accent-soft)] shadow-[0_2px_5px_color-mix(in_srgb,_var(--accent)_12%,_transparent)] focus-visible:border-[var(--accent)] focus-visible:[outline:2px_solid_var(--accent)] focus-visible:[outline-offset:3px] focus-visible:shadow-[0_0_0_4px_color-mix(in_srgb,_var(--accent)_20%,_transparent)]"
                      disabled={pending}
                      onMouseDown={(e) => e.preventDefault()}
                      onClick={() => {
                        const target = lastFocused.current;
                        const field = formRef.current?.querySelector<
                          HTMLInputElement | HTMLTextAreaElement
                        >(`[name=${target}]`);
                        if (field) {
                          const range = selection.current[target];
                          if (
                            field.value.length -
                              (range.end - range.start) +
                              token.length +
                              4 >
                            field.maxLength
                          )
                            return;
                          field.setRangeText(
                            `{{${token}}}`,
                            selection.current[target].start,
                            selection.current[target].end,
                            "end",
                          );
                          field.focus();
                          selection.current[target] = {
                            start: field.selectionStart ?? 0,
                            end: field.selectionEnd ?? 0,
                          };
                          setDirty(true);
                          setResult((current) =>
                            current?.ok ? undefined : current,
                          );
                          syncDraft();
                        }
                      }}
                    >
                      {`{{${token}}}`}
                    </Button>
                  ))}
                  <Button
                    type="button"
                    variant="outline"
                    className="cursor-pointer chip min-h-11 max-w-full whitespace-normal wrap-anywhere [border:1px_dashed_var(--border)] rounded-full [background:transparent] text-link [font:500_12px_ui-monospace,_monospace]"
                    disabled={pending}
                    onMouseDown={(event) => event.preventDefault()}
                    onClick={() => {
                      const field =
                        formRef.current?.querySelector<HTMLTextAreaElement>(
                          '[name="body"]',
                        );
                      if (!field) return;
                      const range = selection.current.body;
                      if (
                        field.value.length - (range.end - range.start) + 1 >
                        field.maxLength
                      )
                        return;
                      field.setRangeText("\n", range.start, range.end, "end");
                      field.focus();
                      selection.current.body = {
                        start: field.selectionStart,
                        end: field.selectionEnd,
                      };
                      setDirty(true);
                      setResult((current) =>
                        current?.ok ? undefined : current,
                      );
                      syncDraft();
                    }}
                  >
                    Line break
                  </Button>
                </div>
              </div>
              <Textarea
                onFocus={() => {
                  lastFocused.current = "body";
                }}
                onSelect={(e) => {
                  selection.current.body = {
                    start: e.currentTarget.selectionStart,
                    end: e.currentTarget.selectionEnd,
                  };
                }}
                id="template-body"
                readOnly={planLocked}
                disabled={pending}
                aria-invalid={!!result?.fieldErrors?.body}
                aria-describedby={
                  result?.fieldErrors?.body ? "error-body" : undefined
                }
                name="body"
                defaultValue={template?.body}
                rows={10}
                className="read-only:cursor-pointer template-message-editor flex-[1_0_auto] h-115 min-h-115 overflow-y-auto resize-y leading-[1.6] text-[15px]"
                required
                maxLength={20000}
                autoComplete="off"
                placeholder="Hi {{name}},…"
              />
              <FieldError result={result} name="body" />
              <div className="template-editor-meta flex flex-wrap justify-between gap-2 text-[12px] text-body wrap-anywhere">
                <span>
                  {words} {words === 1 ? "word" : "words"}
                </span>
                <span
                  id="template-placeholder-errors"
                  role="status"
                  className="max-w-full text-warning"
                >
                  {placeholderErrors.join(" ")}
                </span>
              </div>
            </div>
            <button
              type="button"
              className="template-editor-tips-toggle [align-self:flex-start] min-h-11 text-link text-[13px] cursor-pointer"
              aria-expanded={tipsOpen}
              aria-controls="template-formatting-tips"
              onClick={() => setTipsOpen(!tipsOpen)}
            >
              {tipsOpen ? "Hide tips" : "Formatting tips"}
            </button>
            <div
              id="template-formatting-tips"
              className="template-editor-tips py-3.5 px-4 [border:1px_solid_var(--border)] rounded-[var(--appearance-control-radius,_12px)] [background:var(--surface)] text-body text-[13px] leading-[1.6]"
              hidden={!tipsOpen}
            >
              <p>
                {"{{name}}"} uses the contact’s name; {"{{company}}"} uses their
                company (empty if missing); {"{{role}}"} uses their job role,
                which you can override in Compose. Click a chip to insert at the
                last subject or message cursor.
              </p>
              <p>
                Paste full HTTP/HTTPS links directly into the message. Multiple
                links and line breaks are supported, with a plain-text
                alternative. Use <code className="text-link">**bold**</code> for
                emphasis, <code className="text-link">- </code> or{" "}
                <code className="text-link">* </code> for bullets, and{" "}
                <code className="text-link">1. </code> for numbered lists.
              </p>
              <p>
                Enter = new line; Enter twice = blank line. The Line break
                button inserts a new line at your last message cursor. Automatic
                wrapping depends on the available screen width; outgoing HTML
                messages use a maximum width of 640px.
              </p>
              <p>
                Upload a PDF in Settings, then select “Attach PDF” in Compose.
                Mentioning a PDF in the message does not attach it.
              </p>
              <p>
                When using the example, replace sample links and signature, and
                attach your PDF in Compose or remove the attachment sentence.
              </p>
            </div>
            <Feedback
              planLabel={planLabel}
              result={result}
              successConfirmation
            />
          </form>
        </div>
        <div
          id="template-pane-preview"
          role="tabpanel"
          aria-labelledby="template-tab-preview"
          className={cn(
            "template-editor-preview-pane self-stretch min-w-0",
            tab === "write" && "[@media(max-width:_959px)]:hidden",
          )}
        >
          <TemplatePreview
            contacts={contacts}
            subject={draft.subject}
            body={draft.body}
          />
        </div>
        <div className="template-editor-action-bar backdrop-blur-md fixed [inset:auto_0_0] z-[30] [background:var(--template-editor-bar)] border-t border-dotted border-separator">
          <div className="template-editor-action-inner max-w-370 mx-auto [padding:12px_clamp(16px,_3vw,_40px)_max(12px,_env(safe-area-inset-bottom))] flex items-center justify-between gap-3">
            <span className="template-editor-action-note text-[13px] text-body [@media(max-width:_959px)]:hidden">
              {canSave
                ? "Ready to save"
                : placeholderErrors.length
                  ? "Fix the placeholders to save"
                  : "Add a name, subject and message to save"}
            </span>
            <div className="template-editor-actions flex gap-2.5 [@media(max-width:_959px)]:w-full [@media(max-width:_959px)]:flex-col">
              <Button
                className="cursor-pointer [@media(max-width:_959px)]:w-full"
                type="submit"
                form="template-pane-write"
                disabled={pending || (!planLocked && !canSave)}
                onClick={(event) => {
                  if (!planLocked) return;
                  event.preventDefault();
                  upgrade({
                    feature: "templates",
                    trigger: event.currentTarget,
                  });
                }}
              >
                {pending ? "Saving…" : "Save template"}
              </Button>
              {!template && (
                <Button
                  className="cursor-pointer [@media(max-width:_959px)]:w-full"
                  type="button"
                  variant="outline"
                  disabled={pending}
                  onClick={() => {
                    if (planLocked) return upgrade({ feature: "templates" });
                    if (
                      dirty &&
                      !window.confirm(
                        "Replace your current subject and message with the example?",
                      )
                    )
                      return;
                    for (const key of ["subject", "body"] as const) {
                      const field =
                        formRef.current?.querySelector<HTMLInputElement>(
                          `[name=${key}]`,
                        );
                      if (field) field.value = example[key];
                    }
                    setDirty(true);
                    setResult((current) => (current?.ok ? undefined : current));
                    syncDraft();
                  }}
                >
                  Use Example
                </Button>
              )}
              {(template || cancelHref) && (
                <Button
                  className="cursor-pointer [@media(max-width:_959px)]:w-full"
                  asChild
                  variant="outline"
                >
                  <Link href={cancelHref ?? "/templates"}>Cancel</Link>
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
export function ContactForm({
  contact,
  roles = [],
}: {
  premiumPrice?: PremiumPrice;
  roles?: string[];
  contact?: {
    id: string;
    name: string;
    email: string;
    company: string | null;
    jobRole: string | null;
  };
}) {
  const manualName = useRef(!!contact?.name);
  const [email, setEmail] = useState(contact?.email ?? "");
  const [previouslyEmailed, setPreviouslyEmailed] = useState(false);
  const emailVersion = useRef(0);
  useEffect(() => {
    const parsed = normalizedEmail.safeParse(email);
    if (!parsed.success) return;
    let active = true;
    const version = emailVersion.current;
    const timer = setTimeout(() => {
      startTransition(async () => {
        try {
          const matched = await checkContactEmail(parsed.data);
          if (active && version === emailVersion.current)
            setPreviouslyEmailed(matched);
        } catch {
          // The advisory lookup must never prevent saving a contact.
        }
      });
    }, 300);
    return () => {
      active = false;
      clearTimeout(timer);
    };
  }, [email]);
  const [name, setName] = useState(contact?.name ?? "");
  const [jobRole, setJobRole] = useState(contact?.jobRole ?? "");
  const { list, suggestions } = useRoleSuggestions(roles);
  const [result, setResult] = useState<ActionResult>();
  const [pending, start] = useTransition();
  const [dirty, setDirty] = useState(false);
  useUnsavedChanges(dirty);
  const router = useRouter();
  const notifySuccess = useSuccessNotification();
  const formRef = useRef<HTMLFormElement>(null);
  const focusSubmissionErrors = useRef(false);
  useEffect(() => {
    if (!pending && result?.ok === false && focusSubmissionErrors.current) {
      focusSubmissionErrors.current = false;
      formRef.current
        ?.querySelector<HTMLElement>("[aria-invalid='true']")
        ?.focus();
    }
  }, [result, pending]);
  function clearFieldError(field: string) {
    setResult((current) => {
      if (!current) return current;
      const fieldErrors = { ...current.fieldErrors };
      delete fieldErrors[field];
      return { ok: false, message: "", fieldErrors };
    });
  }
  return (
    <form
      ref={formRef}
      className="contact-form panel space-y-4 p-6"
      onReset={() => {
        emailVersion.current++;
        setPreviouslyEmailed(false);
        setEmail(contact?.email ?? "");
      }}
      onChange={() => {
        setDirty(true);
        setResult((current) => (current?.ok ? undefined : current));
      }}
      onSubmit={(event) => {
        event.preventDefault();
        const form = new FormData(event.currentTarget);
        setResult(undefined);
        start(async () => {
          const r = await saveContact(form);
          focusSubmissionErrors.current = !r.ok;
          setResult(r);
          if (r.ok) {
            emailVersion.current++;
            setPreviouslyEmailed(false);
            notifySuccess("Contact saved successfully.");
            setDirty(false);
            if (!contact) {
              formRef.current?.reset();
              setName("");
              setJobRole("");
              manualName.current = false;
            }
            router.refresh();
          }
        });
      }}
    >
      <h2 className="text-xl font-semibold">
        {contact ? "Edit Contact" : "New Contact"}
      </h2>
      {suggestions}
      {contact && <input type="hidden" name="id" value={contact.id} />}
      {(
        [
          {
            name: "email",
            label: "Email",
            placeholder: "[REDACTED_EMAIL]…",
            max: 254,
          },
          {
            name: "name",
            label: "Name",
            placeholder: "Alex Morgan…",
            max: 120,
          },
          { name: "company", label: "Company", placeholder: "Acme…", max: 160 },
          {
            name: "jobRole",
            label: "Job Role",
            placeholder: "Software Engineer Intern…",
            max: 160,
          },
        ] as const
      ).map((f) => (
        <div key={f.name}>
          <label
            htmlFor={`contact-${f.name}`}
            className="mb-2 block text-sm font-medium"
          >
            {f.label}
            {f.name === "company" && (
              <span className="ml-2 font-normal text-body">Optional</span>
            )}
          </label>
          <Input
            id={`contact-${f.name}`}
            list={f.name === "jobRole" ? list : undefined}
            data-previously-emailed={
              previouslyEmailed && f.name === "email" ? "true" : undefined
            }
            disabled={pending}
            aria-invalid={!!result?.fieldErrors?.[f.name]}
            aria-describedby={
              [
                result?.fieldErrors?.[f.name] ? `error-${f.name}` : "",
                previouslyEmailed && f.name === "email"
                  ? "contact-email-history-note"
                  : "",
              ]
                .filter(Boolean)
                .join(" ") || undefined
            }
            name={f.name}
            type={f.name === "email" ? "email" : "text"}
            defaultValue={
              f.name === "company" ? (contact?.[f.name] ?? "") : undefined
            }
            value={
              f.name === "email"
                ? email
                : f.name === "name"
                  ? name
                  : f.name === "jobRole"
                    ? jobRole
                    : undefined
            }
            onChange={(e) => {
              clearFieldError(f.name);
              if (f.name === "email") {
                emailVersion.current++;
                setPreviouslyEmailed(false);
                setEmail(e.target.value);
              }
              if (f.name === "name") {
                manualName.current = true;
                setName(e.target.value);
              }
              if (f.name === "email" && !manualName.current) {
                setName(suggestName(e.target.value));
                clearFieldError("name");
              }
              if (f.name === "jobRole") setJobRole(e.target.value);
            }}
            required={f.name !== "company"}
            maxLength={f.max}
            autoComplete="off"
            spellCheck={f.name !== "email"}
            placeholder={f.placeholder}
          />
          <FieldError result={result} name={f.name} />
        </div>
      ))}
      <p
        id="contact-email-history-note"
        role="status"
        className="text-sm text-warning"
      >
        {previouslyEmailed
          ? "You’ve already emailed this address. You can still save this contact and send a follow-up."
          : ""}
      </p>
      <p className="text-xs text-body">
        Names from email addresses are suggestions. Correct them before saving.
        Enter actual names, companies, and roles here.
      </p>
      <RoleChoices
        roles={roles}
        disabled={pending}
        onChoose={(r) => {
          setJobRole(r);
          setDirty(true);
          clearFieldError("jobRole");
        }}
      />
      <Feedback result={result} successConfirmation inlineFieldErrors />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {pending ? "Saving…" : "Save Contact"}
        </Button>
        {contact && (
          <Button asChild variant="outline">
            <Link href="/contacts">Cancel</Link>
          </Button>
        )}
      </div>
    </form>
  );
}
